-- =============================================================================
-- Heat Treatment Import (Apr to Jun 2026)
-- Generated on: 2026-09-11 16:00:23
-- =============================================================================

BEGIN;

CREATE TEMP TABLE temp_prod_import (
  work_order_no text,
  stage_code text,
  process_date date,
  input_qty numeric,
  output_qty numeric,
  rejection_qty numeric,
  pcs integer,
  rej_pcs integer,
  heat_lot_no text,
  shift text,
  machine_no text,
  remarks text
) ON COMMIT DROP;













-- Insert matched records into production_logs
  work_order_id,
  stage_id,
  process_route_id,
  process_date,
  input_qty,
  output_qty,
  rejection_qty,
  htc_ok,
  heat_lot_no,
  remarks
)
SELECT
  wo.id AS work_order_id,
  ps.id AS stage_id,
  COALESCE(
    (SELECT rp.process_route_id FROM public.rolling_plans rp WHERE rp.work_order_id = wo.id ORDER BY rp.created_at DESC LIMIT 1),
    (SELECT pr.id FROM public.process_routes pr WHERE pr.route_code = 'CDS' LIMIT 1)
  ) AS process_route_id,
  t.process_date,
  t.input_qty,
  t.output_qty,
  t.rejection_qty,
  0 AS htc_ok,
  t.heat_lot_no,
  TRIM(COALESCE(t.remarks, '') || ' [PCS:' || t.pcs || '] [REJ_PCS:' || t.rej_pcs || ']') AS remarks
FROM temp_prod_import t
JOIN public.work_orders wo ON (
  UPPER(TRIM(wo.work_order_no)) = UPPER(TRIM(t.work_order_no))
  OR UPPER(TRIM(wo.work_order_no)) = UPPER('DOM-' || LPAD(TRIM(t.work_order_no), 5, '0'))
  OR UPPER(TRIM(REPLACE(wo.work_order_no, 'DOM-', ''))) = UPPER(TRIM(REPLACE(t.work_order_no, 'DOM-', '')))
)
JOIN public.process_stages ps ON ps.stage_code = t.stage_code;

DO $body$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT wo.id
    FROM temp_prod_import t
    JOIN public.work_orders wo ON (
      UPPER(TRIM(wo.work_order_no)) = UPPER(TRIM(t.work_order_no))
      OR UPPER(TRIM(wo.work_order_no)) = UPPER('DOM-' || LPAD(TRIM(t.work_order_no), 5, '0'))
      OR UPPER(TRIM(REPLACE(wo.work_order_no, 'DOM-', ''))) = UPPER(TRIM(REPLACE(t.work_order_no, 'DOM-', '')))
    )
  LOOP
    PERFORM public.recalculate_work_order_wip(r.id);
  END LOOP;
END $body$;

COMMIT;
